// Valida la fecha y arma la URL de disponibilidad de app.clinera.io.
// Sin URLSearchParams: el sandbox del Code node de este n8n no lo expone.
// CONFIG: mismos valores que el nodo "Responder Config".
const CONFIG = {
  clinicaUrl: 'clinera-software-1769526763629',
  sucursalId: 'cmoqinfoi007dso3d7fhnwdyb',
  tratamientoId: 'cmoyoj9sn026xoi3dnedn2kl8',
  duracionMin: 45,
};
const fecha = String(($json.query && $json.query.fecha) || '');
if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha)) {
  return [{ json: { ok: false, error: 'fecha inválida (YYYY-MM-DD)' } }];
}
const qs = [
  ['clinicaUrl', CONFIG.clinicaUrl],
  ['sucursalId', CONFIG.sucursalId],
  ['fecha', fecha],
  ['duracionMin', String(CONFIG.duracionMin)],
].map(function (kv) { return kv[0] + '=' + encodeURIComponent(kv[1]); }).join('&');
return [{ json: { ok: true, url: 'https://app.clinera.io/api/public/iframe/disponibilidad?' + qs } }];

// Valida y normaliza el pedido de turno que llega desde www.clinera.io/agenda.
// Replica el flujo del widget embebido: primero upsert del paciente, después la cita.
const CONFIG = {
  clinicaUrl: 'clinera-software-1769526763629',
  sucursalId: 'cmoqinfoi007dso3d7fhnwdyb',
  sucursalNombre: 'Clinera Software',
  tratamientoId: 'cmoyoj9sn026xoi3dnedn2kl8',
  tratamiento: 'Reunión con Clinera',
  duracionMin: 45,
};
const b = $json.body || {};
const nombre = String(b.nombre || '').trim().slice(0, 120);
const email = String(b.email || '').trim().toLowerCase().slice(0, 160);
// La API de Clinera exige solo dígitos (sin '+', espacios ni símbolos).
const telefono = String(b.telefono || '').replace(/\D/g, '').slice(0, 15);
const fecha = String(b.fecha || '');
const hora = String(b.hora || '');
const professionalId = String(b.professionalId || '').slice(0, 64);
const professionalName = String(b.professionalName || '').trim().slice(0, 120);

const errores = [];
if (nombre.length < 2) errores.push('nombre');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errores.push('email');
if (telefono.replace(/\D/g, '').length < 10) errores.push('telefono');
if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha)) errores.push('fecha');
if (!/^\d{2}:\d{2}$/.test(hora)) errores.push('hora');
if (!professionalId && !professionalName) errores.push('profesional');
if (errores.length) {
  return [{ json: { ok: false, error: 'Campos inválidos: ' + errores.join(', ') } }];
}

return [{ json: {
  ok: true,
  config: CONFIG,
  paciente: { name: nombre, email, telefono },
  cita: {
    nombre,
    email,
    telefono,
    fecha,
    hora,
    professionalId: professionalId || undefined,
    doctor: professionalName || undefined,
    notas: 'Turno solicitado desde www.clinera.io/agenda',
    tratamientoId: CONFIG.tratamientoId,
    tratamiento: CONFIG.tratamiento,
    sucursal: CONFIG.sucursalNombre,
    sucursalId: CONFIG.sucursalId,
    sucursalNombre: CONFIG.sucursalNombre,
    duracion: CONFIG.duracionMin,
    createAsNewPatient: false,
  },
} }];

// La cita usa los datos que devolvió el upsert del paciente si vinieron;
// si el POST de paciente falló, sigue con los datos originales (igual que el widget).
const req = $('Validar y Normalizar').first().json;
const resp = $json || {};
const data = resp.data || {};
const cita = { ...req.cita };
if (data.email) {
  cita.nombre = data.name || cita.nombre;
  cita.email = data.email;
  if (data.phone) cita.telefono = String(data.phone).replace(/\D/g, '');
}
return [{ json: { config: req.config, cita } }];

// ===================================================================
// Prepara el evento de conversión "Schedule" (agendamiento confirmado)
// para Meta CAPI y GA4 Measurement Protocol.
//
// Dedupe con el Pixel: el navegador manda su event_id en el body y usa
// EL MISMO en fbq('track','Schedule', ..., { eventID }). Meta deduplica
// por (event_name, event_id), así que Pixel + CAPI = 1 sola conversión.
// Si el turno entra por otro canal (sin event_id), se arma uno
// determinista por turno para no contar dos veces un reintento.
// ===================================================================
const crypto = require('crypto');
const hash = (v) => (v ? crypto.createHash('sha256').update(String(v).trim().toLowerCase()).digest('hex') : '');

const req = $('Validar y Normalizar').first().json;
const cita = req.cita || {};
const wh = $('Webhook Turno').first().json || {};
const body = wh.body || {};
const headers = wh.headers || {};

const email = String(cita.email || '').toLowerCase();
const telefono = String(cita.telefono || '').replace(/\D/g, ''); // dígitos con país
const nombre = String(cita.nombre || '').trim();
const partes = nombre.split(/\s+/).filter(Boolean);
const firstName = partes[0] || '';
const lastName = partes.slice(1).join(' ');

// País por prefijo del teléfono (E.164 sin '+').
const PREFIJOS = [['595','PY'],['593','EC'],['507','PA'],['506','CR'],['56','CL'],['54','AR'],['52','MX'],['51','PE'],['34','ES'],['1','US']];
let country = 'CL';
for (const par of PREFIJOS) { if (telefono.indexOf(par[0]) === 0) { country = par[1]; break; } }

const eventTime = Math.floor(Date.now() / 1000);
const eventId = String(body.event_id || ('mql_' + hash(email).slice(0, 12) + '_' + cita.fecha + '_' + cita.hora));
const ip = String(headers['x-forwarded-for'] || '').split(',')[0].trim();
const ua = String(headers['user-agent'] || '');

// GA4 usa el client_id real de la cookie _ga si el navegador lo mandó;
// si no, uno derivado del email para no inventar un usuario por evento.
const emailHash = hash(email || 'anon');
const gaClientId = String(body.ga_client_id || ((parseInt(emailHash.slice(0, 12), 16) % 1e10) + '.' + eventTime));

const ga4Body = {
  client_id: gaClientId,
  user_id: emailHash,
  timestamp_micros: eventTime * 1000000,
  non_personalized_ads: false,
  events: [{
    name: 'mql',
    params: {
      currency: 'USD',
      value: 0,
      session_id: String(eventTime),
      engagement_time_msec: 100,
      event_source: 'clinera_agenda',
      method: 'agenda_nativa_n8n',
      professional: String(cita.doctor || ''),
      appointment_date: String(cita.fecha || ''),
      appointment_time: String(cita.hora || ''),
      items: [{
        item_id: 'clinera_mql_agendamiento',
        item_name: 'Clinera MQL - Agendamiento',
        item_category: String((req.config && req.config.tratamiento) || 'Reunion con Clinera'),
        price: 0,
        quantity: 1,
      }],
    },
  }],
};

return [{ json: {
  em: hash(email),
  ph: hash(telefono),
  fn: hash(firstName),
  ln: hash(lastName),
  country_hashed: hash(country),
  external_id: hash(email),
  fbc: String(body.meta_fbc || body.fbc || ''),
  fbp: String(body.meta_fbp || body.fbp || ''),
  client_ip_address: ip,
  client_user_agent: ua,
  event_time: eventTime,
  event_id: eventId,
  event_source_url: String(body.event_source_url || 'https://www.clinera.io/agenda'),
  country: country,
  profesional: String(cita.doctor || ''),
  fecha: String(cita.fecha || ''),
  hora: String(cita.hora || ''),
  ga4Body: ga4Body,
} }];
